<style>
/* Profile Completion Floating Toast */
.profile-toast {
  position: fixed;
  bottom: 24px;
  right: 24px;
  z-index: 99999;
  width: min(calc(100vw - 32px), 430px);
  min-height: 110px;
  background: #ecdccb;
  border-radius: 14px;
  box-shadow: 0 16px 36px rgba(56, 34, 24, 0.18), 0 4px 12px rgba(56, 34, 24, 0.08);
  border: none;
  overflow: hidden;
  color: #3b2820;
  animation: toast-smooth-in 0.5s cubic-bezier(0.16, 1, 0.3, 1) 0.25s both;
  transition: opacity 0.35s cubic-bezier(0.4, 0, 0.2, 1), transform 0.35s cubic-bezier(0.4, 0, 0.2, 1);
}

.profile-toast.is-dismissing {
  opacity: 0;
  transform: translateY(22px) scale(0.95);
  pointer-events: none;
}

.profile-toast-inner {
  display: flex;
  align-items: flex-start;
  gap: 14px;
  padding: 16px 20px;
}

.profile-toast-icon {
  width: 44px;
  height: 44px;
  border-radius: 12px;
  background: rgba(122, 75, 58, 0.15);
  color: #7a4b3a;
  display: grid;
  place-items: center;
  flex-shrink: 0;
}

.profile-toast-icon svg {
  width: 22px;
  height: 22px;
}

.profile-toast-body {
  flex: 1;
  min-width: 0;
}

.profile-toast-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 4px;
}

.profile-toast-header strong {
  font-size: 15px;
  font-weight: 700;
  color: #3b2820;
}

.profile-toast-close {
  background: none;
  border: none;
  font-size: 22px;
  line-height: 1;
  color: #7a4b3a;
  cursor: pointer;
  padding: 0 4px;
  transition: color 0.15s, transform 0.15s;
}

.profile-toast-close:hover {
  color: #3b2820;
  transform: scale(1.15);
}

.profile-toast-body p {
  margin: 0 0 12px;
  font-size: 13.5px;
  line-height: 1.45;
  color: #5a4236;
}

.profile-toast-actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 10px;
}

.toast-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 7px 16px;
  border-radius: 8px;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  text-decoration: none;
  transition: all 0.18s ease;
}

.toast-btn--secondary {
  border: 1px solid #d9bea6;
  background: transparent;
  color: #7a4b3a;
}

.toast-btn--secondary:hover {
  background: rgba(122, 75, 58, 0.1);
  color: #3b2820;
}

.toast-btn--primary {
  border: none;
  background: #7a4b3a;
  color: #ffffff;
  font-weight: 700;
  box-shadow: 0 2px 8px rgba(122, 75, 58, 0.25);
}

.toast-btn--primary:hover {
  background: #633b2c;
  transform: translateY(-1px);
}
}

.toast-btn--primary:hover {
  filter: brightness(1.06);
}

@keyframes toast-smooth-in {
  from {
    opacity: 0;
    transform: translateY(28px) scale(0.95);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

@media (max-width: 520px) {
  .profile-toast {
    bottom: 16px;
    right: 16px;
    left: 16px;
    width: auto;
  }
}

.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap;border:0}
.um-toolbar{display:flex;flex-wrap:nowrap;align-items:center;justify-content:flex-start;gap:12px;margin:0 0 16px}
